    private val byIndex: Map<Int, EnemySkillSpec> = entries.associateBy { it.index }

    fun findByIndex(index: Int): EnemySkillSpec? = byIndex[index]

    fun findByName(query: String): List<EnemySkillSpec> {
        val q = query.trim()
        if (q.isEmpty()) return emptyList()
        return entries.filter { it.nameZhTw.contains(q, ignoreCase = true) || it.nameZhCn.contains(q, ignoreCase = true) }
    }

    fun boardRelevantEntries(): List<EnemySkillSpec> =
        entries.filter { it.relevance != SolverRelevance.NON_BOARD_MECHANIC }
}
